package com.bank.sercache.cache;

import com.bank.sercache.model.AccountAgg;
import java.io.*;
import java.util.List;
import java.util.logging.Logger;

// Stores a partition either as live objects (deserialized) or bytes (serialized).
public class CacheBlock {
    private static final Logger log = Logger.getLogger(CacheBlock.class.getName());

    private List<AccountAgg> liveObjects;   // deserialized form
    private byte[] serializedBytes;         // serialized form
    private int serializeOps = 0;
    private int deserializeOps = 0;

    // Store DESERIALIZED: keep live objects — fast access, high memory.
    public void storeDeserialized(List<AccountAgg> objs) {
        this.liveObjects = objs;
        // Model live-object footprint: ~64 bytes JVM overhead per record on top of data.
        long footprint = (long) objs.size() * (64 + 48);
        log.info(() -> "DESERIALIZED store: " + objs.size() + " live objects, ~"
                + footprint + "B (fast read, no conversion)");
    }

    // Store SERIALIZED: pack to a byte array — low memory, CPU to ser/deser.
    public void storeSerialized(List<AccountAgg> objs) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(bos)) {
            oos.writeObject(objs);
        }
        this.serializedBytes = bos.toByteArray();
        this.serializeOps++;
        log.info(() -> "SERIALIZED store: packed to " + serializedBytes.length
                + "B (low memory, +1 serialize op)");
    }

    // Read from the deserialized block: instant, no conversion.
    public List<AccountAgg> readDeserialized() {
        log.fine("read DESERIALIZED: direct object reference (0 CPU conversion)");
        return liveObjects;
    }

    // Read from the serialized block: must deserialize every time.
    @SuppressWarnings("unchecked")
    public List<AccountAgg> readSerialized() throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois =
                 new ObjectInputStream(new ByteArrayInputStream(serializedBytes))) {
            deserializeOps++;
            log.fine(() -> "read SERIALIZED: deserialize (+1 deserialize op)");
            return (List<AccountAgg>) ois.readObject();
        }
    }

    public int getSerializeOps() { return serializeOps; }
    public int getDeserializeOps() { return deserializeOps; }
    public long deserializedFootprint() { return (long) liveObjects.size() * (64 + 48); }
    public long serializedFootprint() { return serializedBytes.length; }
}
