package com.bank.sercache;

import com.bank.sercache.cache.CacheBlock;
import com.bank.sercache.model.AccountAgg;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SerCacheDemo {
    private static final Logger log = Logger.getLogger(SerCacheDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new SerCacheLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        // An aggregate of many accounts (Rajesh, Priya, and others).
        List<AccountAgg> aggs = new ArrayList<>();
        aggs.add(new AccountAgg("SAV2001", new BigDecimal("4000")));
        aggs.add(new AccountAgg("CUR3001", new BigDecimal("500")));
        for (int i = 0; i < 1000; i++) {
            aggs.add(new AccountAgg("ACC" + i, new BigDecimal(i * 100)));
        }

        // Deserialized: fast read, bigger footprint.
        CacheBlock deser = new CacheBlock();
        deser.storeDeserialized(aggs);
        deser.readDeserialized(); // 0 conversion

        // Serialized: smaller footprint, conversion cost on store + each read.
        CacheBlock ser = new CacheBlock();
        ser.storeSerialized(aggs);
        ser.readSerialized();
        ser.readSerialized(); // each read pays deserialize

        log.info(() -> "deserialized footprint = " + deser.deserializedFootprint()
                + "B, conversions = 0");
        log.info(() -> "serialized footprint   = " + ser.serializedFootprint()
                + "B, serializeOps=" + ser.getSerializeOps()
                + ", deserializeOps=" + ser.getDeserializeOps());
    }
}

